package mx.jorge.despierta;
import android.app.*;import android.content.*;import android.media.*;import android.os.*;
public final class AudioSafety {
 static TripService service;static BroadcastReceiver receiver;static AudioDeviceCallback devices;
 public static boolean strict(Context c){return c.getSharedPreferences("appearance",0).getBoolean("onlyHeadphones",false);}
 static boolean headphone(AudioDeviceInfo d){if(d==null)return false;int t=d.getType();return t==AudioDeviceInfo.TYPE_WIRED_HEADSET||t==AudioDeviceInfo.TYPE_WIRED_HEADPHONES||t==AudioDeviceInfo.TYPE_BLUETOOTH_A2DP||t==AudioDeviceInfo.TYPE_USB_HEADSET||(Build.VERSION.SDK_INT>=31&&t==AudioDeviceInfo.TYPE_BLE_HEADSET);}
 public static AudioDeviceInfo headset(Context c){AudioManager m=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);for(AudioDeviceInfo d:m.getDevices(AudioManager.GET_DEVICES_OUTPUTS))if(headphone(d))return d;return null;}
 public static void start(TripService s){service=s;receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(strict(s))mute(s,"Audífonos desconectados · continuando con vibración");}};if(Build.VERSION.SDK_INT>=33)s.registerReceiver(receiver,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY),Context.RECEIVER_NOT_EXPORTED);else s.registerReceiver(receiver,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY));devices=new AudioDeviceCallback(){public void onAudioDevicesRemoved(AudioDeviceInfo[] removed){if(strict(s)&&headset(s)==null)mute(s,"Sin audífonos · continuando con vibración");}};((AudioManager)s.getSystemService(Context.AUDIO_SERVICE)).registerAudioDeviceCallback(devices,new Handler(Looper.getMainLooper()));}
 public static void stop(TripService s){if(receiver!=null)try{s.unregisterReceiver(receiver);}catch(Exception ignored){}if(devices!=null)((AudioManager)s.getSystemService(Context.AUDIO_SERVICE)).unregisterAudioDeviceCallback(devices);receiver=null;devices=null;service=null;}
 static void mute(TripService s,String reason){try{if(JourneyEngine.earlyPlayer!=null)JourneyEngine.earlyPlayer.setVolume(0,0);if(s.player!=null)s.player.setVolume(0,0);}catch(Exception ignored){}if(TripService.ringing){if(!s.alertVibration){s.alertVibration=true;s.vibrateAlarm();}s.update(reason);TripHistory.add(s,reason);}}
 public static boolean allow(TripService s){if(strict(s)&&headset(s)==null){mute(s,"Audio omitido: sin audífonos · vibrando");return false;}return true;}
 public static void configure(TripService s,MediaPlayer player){if(!strict(s))return;player.setVolume(0,0);player.setPreferredDevice(headset(s));player.addOnRoutingChangedListener(router->{if(!strict(s))return;try{if(headphone(player.getRoutedDevice()))player.setVolume(1,1);else mute(s,"Salida de audio no privada · vibrando");}catch(Exception ignored){}},new Handler(Looper.getMainLooper()));}
}
